.sl-hero-video {
  background-color: #0f172a;
  font-family: var(--smartlearn-body-font, system-ui, -apple-system, sans-serif);
  min-height: 85vh;
  padding-block: clamp(3.5rem, 7vw, 6rem);
}
.sl-hero-video .sl-cinematic-overlay {
  background: linear-gradient(120deg, rgba(15, 23, 42, 0.86) 0%, rgba(15, 23, 42, 0.68) 100%);
}
.sl-hero-video .sl-on-dark-text {
  color: #f8fafc;
  font-family: var(--smartlearn-heading-font, var(--smartlearn-body-font, system-ui, -apple-system, sans-serif));
}
.sl-hero-video .sl-on-dark-muted {
  color: #e2e8f0;
}
.sl-hero-video .sl-text-emphasis {
  color: var(--smartlearn-text);
}
.sl-hero-video .sl-text-muted {
  color: var(--smartlearn-text-muted);
}
.sl-hero-video .sl-bg-card {
  background-color: var(--smartlearn-card-bg);
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-video .sl-bg-primary {
  background-color: var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-video .sl-btn-primary {
  background-color: var(--smartlearn-btn-bg);
  border: 1px solid var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-video .sl-btn-primary:hover,
.sl-hero-video .sl-btn-primary:focus-visible {
  background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-video .sl-btn-outline-light {
  border: 2px solid #f8fafc;
  color: #f8fafc;
  background-color: rgba(15, 23, 42, 0.45);
}
.sl-hero-video .sl-btn-outline-light:hover,
.sl-hero-video .sl-btn-outline-light:focus-visible {
  background-color: #f8fafc;
  color: #0f172a;
}
.sl-hero-video .sl-text-shadow {
  text-shadow: 0 4px 20px rgba(0, 0, 0, 0.45);
}
.sl-hero-video .sl-cinematic-title {
  line-height: 1.1;
  letter-spacing: -0.02em;
}
.sl-hero-video .sl-avatar-border {
  border: 2px solid var(--smartlearn-card-border);
}
.sl-hero-video .glass-rating-card {
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.25);
  max-width: 320px;
  transition: transform 0.3s ease;
}
.sl-hero-video .sl-trailer-dialog {
  width: min(860px, 92vw);
  background-color: var(--smartlearn-card-bg);
  color: var(--smartlearn-text);
}
.sl-hero-video .sl-trailer-dialog::backdrop {
  background: rgba(2, 6, 23, 0.8);
}
.sl-hero-video .sl-dialog-bar {
  border-bottom: 1px solid var(--smartlearn-card-border);
}
.sl-hero-video .sl-dialog-close {
  color: var(--smartlearn-text);
}
@media (prefers-reduced-motion: no-preference) {
  .sl-hero-video .glass-rating-card:hover {
    transform: translateY(-5px);
  }
  .sl-hero-video .sl-float-anim {
    animation: sl-hero-creator-float 6s ease-in-out infinite;
  }
}
@media (prefers-reduced-motion: reduce) {
  .sl-hero-video .glass-rating-card,
  .sl-hero-video .sl-float-anim {
    animation: none;
    transition: none;
  }
}
@keyframes sl-hero-creator-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-12px); }
}

