(function() {
  'use strict';
  function toSafeEmbedUrl(rawUrl) {
    if (!rawUrl || typeof rawUrl !== 'string') return null;
    try {
      var u = new URL(rawUrl.trim(), window.location.origin);
      if (u.protocol !== 'https:') return null;
      if (u.hostname === 'www.youtube.com' || u.hostname === 'youtube.com' || u.hostname === 'www.youtube-nocookie.com') {
        if (u.pathname.indexOf('/embed/') === 0) {
          u.searchParams.set('autoplay', '1');
          return u.toString();
        }
      }
      if (u.hostname === 'player.vimeo.com' && u.pathname.indexOf('/video/') === 0) {
        u.searchParams.set('autoplay', '1');
        return u.toString();
      }
      return null;
    } catch (e) {
      return null;
    }
  }
  function initCreatorHeroes() {
    var roots = document.querySelectorAll('.sl-hero-video');
    if (!roots.length) return;
    roots.forEach(function(root) {
      if (root.dataset.slInit === '1') return;
      root.dataset.slInit = '1';
      var trigger = root.querySelector('.sl-trailer-trigger');
      var dialog = root.querySelector('.sl-trailer-dialog');
      var closeBtn = root.querySelector('.sl-dialog-close');
      var frameWrap = root.querySelector('.sl-dialog-frame-wrap');
      if (!trigger || !dialog || !frameWrap) return;
      function closeModal() {
        while (frameWrap.firstChild) frameWrap.removeChild(frameWrap.firstChild);
        if (dialog.open) dialog.close();
        trigger.focus();
      }
      trigger.addEventListener('click', function(e) {
        if (root.querySelector('[data-sl-edit-id]')) return;
        e.preventDefault();
        var safeSrc = toSafeEmbedUrl(trigger.getAttribute('data-video-url'));
        if (!safeSrc) return;
        while (frameWrap.firstChild) frameWrap.removeChild(frameWrap.firstChild);
        var iframe = document.createElement('iframe');
        iframe.src = safeSrc;
        iframe.title = 'Course trailer video';
        iframe.referrerPolicy = 'strict-origin-when-cross-origin';
        iframe.setAttribute('allow', 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture');
        iframe.setAttribute('allowfullscreen', 'true');
        frameWrap.appendChild(iframe);
        if (typeof dialog.showModal === 'function') dialog.showModal();
      });
      if (closeBtn) closeBtn.addEventListener('click', closeModal);
      dialog.addEventListener('cancel', function(ev) {
        ev.preventDefault();
        closeModal();
      });
      dialog.addEventListener('click', function(ev) {
        if (ev.target === dialog) closeModal();
      });
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initCreatorHeroes);
  } else {
    initCreatorHeroes();
  }
})();
